/**
 * @summary Send a gift
 */
export const getSendGiftUrl = () => {
  return `/api/gifts/send`;
};

export const sendGift = async (
  sendGiftRequest: SendGiftRequest,
  options?: RequestInit,
): Promise<SendGiftResponse> => {
  return customFetch<SendGiftResponse>(getSendGiftUrl(), {
    ...options,
    method: "POST",
    headers: { "Content-Type": "application/json", ...options?.headers },
    body: JSON.stringify(sendGiftRequest),
  });
};

export const getSendGiftMutationOptions = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof sendGift>>,
    TError,
    { data: BodyType<SendGiftRequest> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof sendGift>>,
  TError,
  { data: BodyType<SendGiftRequest> },
  TContext
> => {
  const mutationKey = ["sendGift"];
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation &&
      "mutationKey" in options.mutation &&
      options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof sendGift>>,
    { data: BodyType<SendGiftRequest> }
  > = (props) => {
    const { data } = props ?? {};

    return sendGift(data, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

